import postgres from "postgres";
import { readFileSync } from "node:fs";

// Hand-written demo artifacts (OpenRouter has no credits), inserted like the builder would save them.
const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: () => {} });
const [u] = await db`select id from auth.users where email=${process.env.E2E_USER_EMAIL}`;
const [w] = await db`select id from workspaces where owner_id=${u.id}`;
await db`delete from artifacts where id=${readFileSync(".qa/probe-id", "utf8").trim()}`;
const period = { from: "2026-08-01", to: "2026-10-31" };
const q = (name, metric, groupBy, extra = {}) => ({ name, source: "investigate", input: { version: 1, period, metric, groupBy, ...extra } });
const artifacts = [
  ["Where your money went", "Show my top merchants since August with a slider to see what cutting back on one would save in a year", ".qa/a-merchants.html",
    [q("merchants", "spending", ["merchant"], { sort: "current-desc", page: { size: 8 } })]],
  ["Income vs spending", "Income vs spending per month since August 2026 and my savings rate, with a what-if for spending less", ".qa/a-savings.html",
    [q("income", "income", ["month"], { sort: "key" }), q("spending", "spending", ["month"], { sort: "key" })]],
  ["Subscriptions check", "List my recurring subscriptions and what they cost per year", ".qa/a-merchants.html",
    [q("merchants", "spending", ["merchant"], { sort: "current-asc", page: { size: 6 } })]],
];
for (const [title, prompt, file, queries] of artifacts) {
  const [a] = await db`insert into artifacts (workspace_id, title) values (${w.id}, ${title}) returning id`;
  await db`insert into artifact_versions (workspace_id, artifact_id, version, prompt, html, queries, model) values (${w.id}, ${a.id}, 1, ${prompt}, ${readFileSync(file, "utf8")}, ${db.json(queries)}, 'hand-written demo')`;
  console.log(a.id, title);
}
await db.end();

