import { chromium } from "@playwright/test";
import postgres from "postgres";

// Median full-document server time (streamed HTML finished) for each page, Home with and without pins.
const db = postgres(process.env.SUPABASE_DB_URL, { max: 1, onnotice: () => {} });
const [{ id: workspace }] = await db`select w.id from workspaces w join auth.users u on u.id=w.owner_id where u.email=${process.env.E2E_USER_EMAIL}`;
const browser = await chromium.launch();
const context = await browser.newContext({ storageState: "e2e/.auth.json", baseURL: "http://localhost:3017" });
const median = async (path, runs = 7) => {
  const times = [];
  for (let i = 0; i < runs + 1; i++) {
    const t = performance.now();
    const response = await context.request.get(path);
    await response.body();
    if (!response.ok()) throw new Error(`${path} ${response.status()}`);
    if (i) times.push(performance.now() - t); // first run warms up
  }
  return Math.round(times.sort((a, b) => a - b)[Math.floor(times.length / 2)]);
};
const setPins = items => db`insert into dashboard_layouts (workspace_id, items) values (${workspace}, ${items}) on conflict (workspace_id) do update set items=excluded.items, version=dashboard_layouts.version+1`;
const builtins = ["overview", "spending", "recent", "insights", "upcoming", "planning", "accounts", "goals"];
await setPins(builtins);
console.log("Home, no pinned artifacts:", await median("/"), "ms");
await setPins(["overview", "artifact:86fdb2e1-c2c0-40c7-8a65-174389a262cb", "artifact:f8eba9fa-e9a5-4cba-97da-398b7d7e1cd6", ...builtins.slice(1)]);
console.log("Home, 2 pinned artifacts:", await median("/"), "ms");
console.log("Artifacts gallery (3 cards):", await median("/ai/artifacts"), "ms");
console.log("Artifact viewer:", await median("/ai/artifacts/86fdb2e1-c2c0-40c7-8a65-174389a262cb"), "ms");
console.log("One frame (queries + HTML, loads after the page):", await median("/ai/artifacts/86fdb2e1-c2c0-40c7-8a65-174389a262cb/frame?view=widget"), "ms");
await db`delete from dashboard_layouts where workspace_id=${workspace}`;
await browser.close();
await db.end();

