if (window.MONEO_VIEW === "widget") document.body.classList.add("widget");
const data = window.MONEO_DATA.tx;
const fmt = minor => new Intl.NumberFormat(undefined, { style: "currency", currency: "EUR" }).format(Number(minor) / 100);
const esc = text => String(text).replace(/&/g, "&amp;").replace(/</g, "&lt;");
if (!data || data.error) { document.getElementById("total").textContent = data ? data.error : "No data"; }
else {
  const sums = {};
  for (const t of data) if (t.currency_code === "EUR" && t.confirmedSpending && Number(t.amount_minor) < 0) sums[t.description] = (sums[t.description] || 0) - Number(t.amount_minor);
  const groups = Object.entries(sums).map(([name, minor]) => ({ name, minor })).sort((a, b) => b.minor - a.minor).slice(0, 8);
  const total = groups.reduce((s, g) => s + g.minor, 0), max = Math.max(...groups.map(g => g.minor));
  document.getElementById("total").textContent = fmt(total);
  const shown = window.MONEO_VIEW === "widget" ? groups.slice(0, 5) : groups;
  document.getElementById("rows").innerHTML = shown.map(g => `<div class="row"><span>${esc(g.name)}</span><span class="bar"><i style="width:${(g.minor / max * 100).toFixed(1)}%"></i></span><span class="amt">${fmt(g.minor)}</span></div>`).join("");
  const pick = document.getElementById("pick"), cut = document.getElementById("cut");
  pick.innerHTML = groups.map((g, i) => `<option value="${i}">${esc(g.name)}</option>`).join("");
  const update = () => { document.getElementById("pct").textContent = cut.value + "%"; document.getElementById("save").textContent = "≈ " + fmt(groups[pick.value].minor / 3 * 12 * cut.value / 100); };
  pick.oninput = cut.oninput = update; update();
}
</script></body></html>

